diagnostic_scripts.ef-pressure-diagnostic.py:
import json,sys,time,statistics,math
from itertools import cycle
from eventflow import EventBus
from benchmarks._runner import benchmark_metadata
rows=[]
for routes in (16,65,256,1000):
 for wildcard in (0,1024):
  for profile in ('uniform','late-hot'):
   with EventBus(routing_key=lambda event:event) as bus:
    for key in range(routes):bus.subscribe(lambda event:None,routing_key=key)
    for _ in range(wildcard):bus.subscribe(lambda event:None)
    for key in range(min(routes,64)):bus.publish(key)
    keys=list(range(routes)) if profile=='uniform' else [routes-1]
    samples=[]
    for i in range(2000):
     event=keys[i%len(keys)];start=time.perf_counter_ns();bus.publish(event);samples.append(time.perf_counter_ns()-start)
    cpu=time.process_time();wall=time.perf_counter()
    for i in range(2000):bus.publish(keys[i%len(keys)])
    elapsed=time.perf_counter()-wall;cpu=time.process_time()-cpu
    hits=0
    for i in range(2000):
     event=keys[i%len(keys)];hits+=event in bus._route_snapshots;bus.publish(event)
    rows.append(dict(routes=routes,wildcard=wildcard,profile=profile,samples_ns=samples,
     p50_ns=statistics.median(samples),p99_ns=sorted(samples)[math.ceil(.99*len(samples))-1],
     publishes_per_second=2000/elapsed,cpu_seconds=cpu,cache_hit_ratio=hits/2000,
     retained_snapshot_bytes=sys.getsizeof(bus._route_snapshots)+sum(sys.getsizeof(x) for x in bus._route_snapshots.values())))
json.dump(dict(metadata=benchmark_metadata(),rows=rows),sys.stdout)

