path=Path('/tmp/ef-history-before.py');path.write_text(source)
spec=importlib.util.spec_from_file_location('eventflow._history_before',path);mod=importlib.util.module_from_spec(spec);spec.loader.exec_module(mod)
rows=[]
for name,cls in [('before',mod.MemoryEventHistory),('after',MemoryEventHistory)]:
 for size in (1000,10000,100000):
  for position in ('first','last','none'):
   for operation in ('query','latest'):
    samples=[];hits=[]
    for repeat in range(5):
     history=cls(size)
     for i in range(size):history.append(1 if (position=='first' and i==0 or position=='last' and i==size-1) else 'x')
     filt=EventFilter(event_type=int);call=getattr(history,operation)
     start=time.perf_counter_ns();call(filt);samples.append(time.perf_counter_ns()-start)
     start=time.perf_counter_ns()
     for _ in range(20):call(filt)
     hits.append((time.perf_counter_ns()-start)/20)
    rows.append(dict(implementation=name,size=size,position=position,operation=operation,cold_ns=samples,warm_ns=hits))
